'''Welcome tour, writing-help set-up, folder reminder and heading spacing. Run by ui-test.py, or alone.'''
import asyncio,re,os
from playwright.async_api import async_playwright
HERE=os.path.dirname(os.path.abspath(__file__))
MOCK=re.search(r"MOCK='''(.*?)'''",open(os.path.join(HERE,'ui-test.py')).read(),re.S).group(1).replace('\\\\','\\')
FRESH="try{if(!sessionStorage.getItem('k')){localStorage.clear();sessionStorage.setItem('k','1')}}catch(e){};window.FS.running=false;window.FS.ollama=false;"
MOCK=MOCK.replace('__LEGACY__',open(os.path.join(HERE,'legacy-seed.json')).read())
fails=[]
def ok(name,cond,extra=''):
    print(('  ok  ' if cond else 'FAIL  ')+name+(' '+str(extra) if not cond else ''))
    if not cond:fails.append(name)
async def page(b,extra='',pre=''):
    pg=await b.new_page(viewport={'width':1440,'height':900});errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    await pg.add_init_script(pre);await pg.add_init_script(MOCK);await pg.add_init_script(extra)
    await pg.goto('file://'+os.path.join(HERE,'..','ui','index.html'));await pg.wait_for_timeout(900);return pg,errs
